const http = require('http');

const baseUrl = 'http://localhost:3001/mcp/search_in_files';
const projectRoot = $vars.projectRoot || '.';
const authToken = $vars.authToken || '';

const searchQuery = typeof $query !== 'undefined' ? $query : '';
const filePat = typeof $filePattern !== 'undefined' ? $filePattern : '';

if (!searchQuery) return 'Error: query is required';

const body = JSON.stringify({
  parameters: { query: searchQuery, filePattern: filePat }
});

return new Promise((resolve, reject) => {
  const req = http.request(baseUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(body),
      'Authorization': 'Bearer ' + authToken,
      'X-Project-Root': encodeURIComponent(projectRoot)
    }
  }, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => {
      if (res.statusCode !== 200) {
        resolve('Error: ' + res.statusCode);
      } else {
        resolve(data);
      }
    });
  });

  req.on('error', (err) => resolve('Error: ' + err.message));
  req.write(body);
  req.end();
});
